const root = document.documentElement;
const sceneHost = document.getElementById('scene');
const contentResponse = await fetch('data/content.json');
if (!contentResponse.ok) throw new Error('無法讀取網站內容');
const content = await contentResponse.json();
const islands = content.islands;
const places = [content.center, ...islands];
const byId = Object.fromEntries(places.map(place => [place.id, place]));
let world = null;
const themeColors = {morning:{sky:'#bcd9d0',sea:'#6bb4aa',fog:'#bcd9d0'},mist:{sky:'#b5d8dc',sea:'#55aeb3',fog:'#c5dfe0'},night:{sky:'#253648',sea:'#173e4c',fog:'#273c4b'}};
const mode = {theme:localStorage.getItem('wood-theme')||'morning',time:'day',reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,quality:'high',panelId:null,mode:'experience',fpsFrames:0,fpsStart:performance.now(),lowSince:null,done:new Set(readArray('wood-visited')),quizzes:new Set(readArray('wood-quizzes')),inventory:readObject('wood-bag',{shell:3,seed:0,flower:0,postcard:0}),currentResident:null,toastTimer:null,season:0};
function readArray(key){try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return []}}
function readObject(key,fallback){try{return {...fallback,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{return {...fallback}}}
const tradeLabel={shell:'🐚 貝殼',seed:'🌱 種子',flower:'🌼 花苗',postcard:'💌 明信片'};
tradeLabel.wood='🪵 木料';tradeLabel.sapling='🌳 樹苗';
function saveState(){localStorage.setItem('wood-visited',JSON.stringify([...mode.done]));localStorage.setItem('wood-quizzes',JSON.stringify([...mode.quizzes]));localStorage.setItem('wood-bag',JSON.stringify(mode.inventory))}
function toast(message){const node=document.getElementById('toast');node.textContent=message;node.classList.add('show');clearTimeout(mode.toastTimer);mode.toastTimer=setTimeout(()=>node.classList.remove('show'),2600)}
function setTheme(theme){if(!['morning','mist','night'].includes(theme))return;mode.theme=theme;root.dataset.theme=theme;localStorage.setItem('wood-theme',theme);document.querySelectorAll('[data-theme-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===theme)));if(theme==='night'){setTimeMode('night')}world?.setPalette();document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='night'?'#16222e':theme==='mist'?'#dcebee':'#f6f0e4')}
function setTimeMode(time){mode.time=time;document.querySelectorAll('[data-time]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.time===time)));if(time==='realtime'){const now=new Date();const h=now.getHours()+now.getMinutes()/60;mode.hour=h;mode.season=classifyHour(h);mode.realtime=true}else if(time==='auto'){mode.hour=8;mode.season=0;mode.realtime=false}else{mode.realtime=false;mode.season=time==='day'?0:time==='dusk'?1:2;mode.hour=time==='day'?10:time==='dusk'?18:23}mode.transitionStart=mode.reduced?null:performance.now();mode.fromSeason=world?.season??mode.season;mode.toSeason=mode.season;mode.transitionProgress=0;updateClock()}
function classifyHour(h){if(h>=6&&h<16)return 0;if(h>=16&&h<20)return 1;return 2}
function updateClock(){const now=new Date();let h=mode.hour??8.5;if(mode.time==='auto'){h=(8.5+(performance.now()/1000/150*24))%24;mode.hour=h;mode.season=classifyHour(h)}if(mode.time==='realtime'){h=now.getHours()+now.getMinutes()/60;mode.hour=h;mode.season=classifyHour(h)}const hr=Math.floor(h),min=Math.floor((h-hr)*60);const labels=['白天','黃昏','夜晚'];const phase=mode.time==='auto'?'自動流動':mode.time==='realtime'?'跟隨現在':labels[mode.season||0];document.getElementById('clockText').textContent=`${phase} ${String(hr).padStart(2,'0')}:${String(min).padStart(2,'0')}`}
function renderProgress(){const total=places.length,count=mode.done.size,quizCount=mode.quizzes.size;document.getElementById('progressCount').textContent=`${count} / ${total}`;document.getElementById('progressFill').style.width=`${count/total*100}%`;document.getElementById('quizProgress').textContent=`${quizCount} / ${total}`;document.getElementById('progressDots').innerHTML=places.map((place,i)=>`<button type="button" class="${mode.done.has(place.id)?'done ':''}${i===0?'center-dot':''}" aria-label="${mode.done.has(place.id)?'已探索':'尚未探索'}：${escapeHtml(place.name)}" data-open="${place.id}">${i===0?'中':String(i).padStart(2,'0')}</button>`).join('');document.getElementById('progressDots').querySelectorAll('[data-open]').forEach(btn=>btn.addEventListener('click',()=>openPlace(btn.dataset.open)));document.getElementById('certificateBtn').disabled=count<total||quizCount<total}
function renderBag(){document.getElementById('inventory').innerHTML=Object.entries(tradeLabel).map(([key,label])=>`<span class="inventory-chip">${label} × ${mode.inventory[key]||0}</span>`).join('')}
function renderCards(filter=''){const q=filter.trim().toLowerCase();const filtered=places.filter(place=>!q||`${place.name} ${place.intro} ${place.r||''} ${place.points?.join(' ')} ${place.support?.join(' ')}`.toLowerCase().includes(q));document.getElementById('placeCards').innerHTML=filtered.map((place,i)=>`<button type="button" class="place-card ${place.id==='center'?'center-place':''}" data-open="${place.id}"><span class="place-card-top"><span class="place-order">${place.id==='center'?'中央島':`ISLAND · 0${place.order}`}</span><span class="place-icon">${place.id==='center'?'✦':['✳','◌','↗','⌁','✧'][i-1]}</span></span><strong class="place-name">${escapeHtml(place.name)}</strong><span class="place-r">${escapeHtml(place.r||'討論與回顧')}</span><span class="place-intro">${escapeHtml(place.intro)}</span>${mode.done.has(place.id)?'<span class="visited">✓ 已走訪</span>':''}</button>`).join('');document.getElementById('placeCards').querySelectorAll('[data-open]').forEach(card=>card.addEventListener('click',()=>openPlace(card.dataset.open)));renderList()}
function renderList(){
  const list=document.getElementById('listView');
  list.innerHTML=places.map(place=>{
    const sections=[];
    if(place.scenario)sections.push('<p><strong>生活情境：</strong>'+escapeHtml(place.scenario)+'</p>');
    sections.push('<p><strong>內容重點：</strong>'+escapeHtml((place.points||[]).join('；'))+'</p>');
    sections.push('<p><strong>可以怎麼支持：</strong>'+escapeHtml((place.support||[]).join('；'))+'</p>');
    if(place.activity)sections.push('<p><strong>動手試試：</strong>'+escapeHtml(place.activity)+'</p>');
    if(place.lesson){sections.push('<p><strong>帶領流程：</strong>'+escapeHtml(place.lesson.map(s=>s.minutes+' 分鐘｜'+s.title+'：'+s.body).join('；'))+'</p>');sections.push('<p><strong>討論問題：</strong>'+escapeHtml(place.questions.join('；'))+'</p>')}
    sections.push('<p><strong>小測驗：</strong>'+escapeHtml(place.quiz.question)+' '+escapeHtml(place.quiz.options.join('／'))+'</p>');
    sections.push('<div class="list-residents"><strong>居民與對話：</strong>'+(place.residents||[]).map(r=>escapeHtml(r.name)+'（'+escapeHtml(r.job)+'）：'+escapeHtml(r.lines.join(' '))).join('　')+'</div>');
    return '<article class="list-row"><h3>'+escapeHtml(place.name)+(place.r?'｜'+escapeHtml(place.r):'')+'</h3><p>'+escapeHtml(place.intro)+'</p><details><summary>閱讀完整情境、支持策略、題目與居民對話</summary>'+sections.join('')+'</details></article>';
  }).join('');
}function openPlace(id){const place=byId[id];if(!place)return;mode.panelId=id;mode.mode='experience';mode.done.add(id);saveState();renderProgress();renderCards(document.getElementById('searchInput').value);hideBubble();const isCenter=id==='center';const panel=document.getElementById('detailPanel');panel.innerHTML=`<button class="panel-close" type="button" aria-label="關閉內容">×</button><div class="panel-kicker">${isCenter?'中央島・討論教室':`島嶼 0${place.order} / 05`}</div><h2 id="panelTitle" class="panel-title">${escapeHtml(place.name)}</h2>${place.r?`<div class="panel-r">${escapeHtml(place.r)}</div>`:''}<p class="panel-intro">${escapeHtml(place.intro)}</p>${place.scenario?`<div class="panel-scene"><strong>走進這段生活情境</strong>${escapeHtml(place.scenario)}</div>`:''}<div class="draft-notice">示意草稿｜以下情境與支持方式依目前提供的簡介編寫，尚待校方及相關專業人員確認。</div><div class="mode-toggle" role="group" aria-label="切換情境模式"><button data-mode="experience" aria-pressed="true" type="button">生活體驗</button><button data-mode="support" aria-pressed="false" type="button">支持模式</button></div><div class="panel-section" id="modeContent"></div>${place.activity?`<div class="panel-section"><h3>✋ 動手試試</h3><p style="font-size:11px;color:var(--muted);line-height:1.7">${escapeHtml(place.activity)}</p><div class="scenario-choice"><button type="button" data-choice="a">先觀察、想一想</button><button type="button" data-choice="b">選一個行動</button></div><div class="scenario-result" hidden></div></div>`:''}${place.lesson?`<div class="panel-section"><h3>⏱ 45 分鐘帶領流程</h3><ul>${place.lesson.map(s=>`<li><strong>${s.minutes} 分鐘｜${escapeHtml(s.title)}</strong>：${escapeHtml(s.body)}</li>`).join('')}</ul></div><div class="panel-section"><h3>一起討論</h3><ul>${place.questions.map(q=>`<li>${escapeHtml(q)}</li>`).join('')}</ul><button class="secondary-button" type="button" data-print>列印討論流程</button></div>`:''}<div class="panel-section"><h3>島上的居民</h3><div class="resident-list">${(place.residents||[]).map((r,i)=>`<div class="resident-row"><span class="resident-dot">${['🌿','🪵'][i%2]}</span><span><strong>${escapeHtml(r.name)}</strong><small>${escapeHtml(r.job)}</small></span><button type="button" data-talk="${i}">聊聊</button></div>`).join('')}</div>${!isCenter?`<div class="panel-trade"><span>🎒 交換：${tradeForIsland(id)}</span><button type="button" data-trade="${id}">試著交換</button></div>`:''}</div><div class="panel-section"><h3>島嶼小測驗</h3><button class="secondary-button" type="button" data-quiz="${id}">${mode.quizzes.has(id)?'再做一次小測驗':'開始這座島的小測驗'}</button></div><p class="draft-notice">這只是部分經驗的模擬，每個人的感受都不一樣。</p><div class="panel-actions"><button class="secondary-button" type="button" data-share="${id}">↗ 分享這座島</button><button class="primary-button" type="button" data-close>回到群島</button></div>`;panel.hidden=false;document.getElementById('panelBackdrop').hidden=false;document.body.classList.add('panel-open');renderModeContent(place);panel.querySelector('.panel-close').addEventListener('click',closePanel);panel.querySelector('[data-close]').addEventListener('click',closePanel);panel.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{mode.mode=button.dataset.mode;panel.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderModeContent(place)}));panel.querySelectorAll('[data-talk]').forEach(button=>button.addEventListener('click',()=>showResident(place,Number(button.dataset.talk))));const tradeButton=panel.querySelector('[data-trade]');if(tradeButton){const offer=content.trades.find(t=>t.island===id);tradeButton.disabled=!!offer&&(mode.inventory[offer.give]||0)<offer.cost;tradeButton.addEventListener('click',()=>trade(place.id))}panel.querySelector('[data-quiz]')?.addEventListener('click',()=>openQuiz(place.id));panel.querySelector('[data-print]')?.addEventListener('click',()=>printLesson(place));panel.querySelector('[data-share]')?.addEventListener('click',()=>sharePlace(place));panel.querySelectorAll('[data-choice]').forEach(button=>button.addEventListener('click',()=>{const result=panel.querySelector('.scenario-result');result.hidden=false;result.textContent=mode.mode==='support'?'支持模式：先提供清楚的物品資訊、適當的大人協助與可行選項，再依校園實際情況決定。':'你選擇先觀察。看看物品現況、實際需求，再一起討論下一步。'}));panel.focus?.();if(world?.islandTargets[id])world.focus(world.islandTargets[id].position);}
function renderModeContent(place){
  const target=document.getElementById('modeContent');
  if(!target)return;
  const support=mode.mode==='support';
  const data=support?place.support:place.points;
  const heading=support?'✦ 可以怎麼支持':'◉ 留意這些生活觀察';
  const comparison=support&&place.scenario?("<div class=\"scenario-result\"><strong>原來的情境：</strong>"+escapeHtml(place.scenario)+"<br><strong>加入支持後：</strong>"+escapeHtml(place.support[0]||"先聽取需要，再討論可行做法。")+" "+escapeHtml(place.support[1]||"依實際情況共同調整。")+"</div><button class=\"secondary-button\" type=\"button\" data-replay>↻ 回到生活體驗</button>"):"";
  target.innerHTML="<h3>"+heading+"</h3><ul>"+data.map(text=>"<li>"+escapeHtml(text)+"</li>").join("")+"</ul>"+comparison;
  target.querySelector('[data-replay]')?.addEventListener('click',()=>{mode.mode='experience';document.querySelectorAll('#detailPanel [data-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mode==='experience')));renderModeContent(place);toast('已切回原始生活情境')});
}function closePanel(){document.getElementById('detailPanel').hidden=true;document.getElementById('panelBackdrop').hidden=true;document.body.classList.remove('panel-open');mode.panelId=null;hideBubble();world?.resetView()}
function tradeForIsland(id){const trade=content.trades.find(item=>item.island===id);return trade?`${trade.cost} ${trade.giveLabel} → ${trade.getLabel}`:'逛逛島上的居民'}
function trade(id){const item=content.trades.find(t=>t.island===id);if(!item){toast('居民今天沒有新的交換提案');return}if((mode.inventory[item.give]||0)<item.cost){toast(`還差一些${item.giveLabel}，可以去沙灘撿貝殼或先完成上一段交換。`);return}mode.inventory[item.give]-=item.cost;mode.inventory[item.get]=(mode.inventory[item.get]||0)+1;saveState();renderBag();const bag=document.getElementById('inventory');bag.classList.remove('bump');void bag.offsetWidth;bag.classList.add('bump');toast(`交換成功，收到 ${item.getLabel}！`);const button=document.querySelector('#detailPanel [data-trade]');if(button)button.disabled=(mode.inventory[item.give]||0)<item.cost;const npc=world?.findResident(id);if(npc)npc.waveUntil=performance.now()+1200;}
function showResident(place,index,anchor=null){const r=anchor?{name:anchor.name,job:anchor.job,lines:anchor.lines}:place.residents?.[index];if(!r)return;if(world)world.focusResident(`${place.id}:${index}`);mode.currentResident={place,index,line:0,anchor:anchor||world?.getResident(place.id,index)};if(mode.panelId){const panel=document.getElementById('detailPanel');let inline=panel.querySelector('.inline-resident-talk');if(!inline){inline=document.createElement('div');inline.className='inline-resident-talk';panel.querySelector('.panel-intro')?.insertAdjacentElement('afterend',inline)}inline.innerHTML='<strong>'+escapeHtml(r.name)+'・'+escapeHtml(r.job)+'</strong><p class="inline-talk-line">'+escapeHtml(r.lines[0])+'</p><div class="bubble-actions"><button type="button" data-more>💬 再聊聊</button><button type="button" data-trade>🔁 交易</button><button type="button" data-hide>✕ 關閉</button></div>';inline.hidden=false;inline.querySelector('[data-more]').addEventListener('click',()=>{mode.currentResident.line=(mode.currentResident.line+1)%r.lines.length;inline.querySelector('.inline-talk-line').textContent=r.lines[mode.currentResident.line]});inline.querySelector('[data-trade]').addEventListener('click',()=>trade(place.id));inline.querySelector('[data-hide]').addEventListener('click',hideBubble);inline.scrollIntoView({block:'nearest',behavior:mode.reduced?'instant':'smooth'});return}const bubble=document.getElementById('residentBubble');bubble.innerHTML=`<div class="bubble-head">${escapeHtml(r.name)} <span>揮揮手</span></div><div class="bubble-meta">${escapeHtml(r.job)}・${escapeHtml(place.name)}</div><div class="bubble-line">${escapeHtml(r.lines[0])}</div><div class="bubble-actions"><button type="button" data-more>💬 再聊聊</button><button type="button" data-trade>🔁 交易</button><button type="button" data-hide>✕ 關閉</button></div>`;bubble.hidden=false;bubble.style.left='50%';bubble.style.top='52%';bubble.querySelector('[data-more]').addEventListener('click',()=>{mode.currentResident.line=(mode.currentResident.line+1)%r.lines.length;bubble.querySelector('.bubble-line').textContent=r.lines[mode.currentResident.line]});bubble.querySelector('[data-trade]').addEventListener('click',()=>trade(place.id));bubble.querySelector('[data-hide]').addEventListener('click',hideBubble);}
function hideBubble(){const bubble=document.getElementById('residentBubble');if(bubble)bubble.hidden=true;document.querySelector('#detailPanel .inline-resident-talk')?.setAttribute('hidden','');mode.currentResident=null}
function openQuiz(id){const place=byId[id];if(!place?.quiz)return;const quiz=place.quiz;const dialog=document.getElementById('quizDialog');dialog.innerHTML=`<form method="dialog"><button class="modal-close" aria-label="關閉">×</button><div class="eyebrow">${id==='center'?'中央島':'島嶼小測驗'}</div><h2>${escapeHtml(quiz.question)}</h2><div class="quiz-options">${quiz.options.map((option,i)=>`<button class="quiz-option" type="button" data-answer="${i}">${escapeHtml(option)}</button>`).join('')}</div><div class="quiz-result" hidden></div><button class="primary-button modal-done" type="submit">完成</button></form>`;dialog.showModal();dialog.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>{const correct=Number(button.dataset.answer)===quiz.answer;const result=dialog.querySelector('.quiz-result');result.hidden=false;result.textContent=`${correct?'答對了！':'再想一想。'} ${quiz.explanation}`;dialog.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(Number(b.dataset.answer)===quiz.answer)b.style.borderColor='#2f7a6b'});if(correct){mode.quizzes.add(id);saveState();renderProgress();toast('完成一題，觀察得真仔細！')}else{button.style.borderColor='#d9792f'}}));}
async function sharePlace(place){const text=`我正在探索「${place.name}」｜木語重生-5R實踐`;try{await navigator.clipboard.writeText(`${text} ${location.href.split('?')[0]}?island=${encodeURIComponent(place.id)}`);toast('島嶼名稱與連結已複製，可以分享給同學。')}catch{toast('分享連結：'+`${location.href.split('?')[0]}?island=${encodeURIComponent(place.id)}`)}}
function guide(){const input=document.getElementById('guideInput'),answer=document.getElementById('guideAnswer'),q=input.value.trim().toLowerCase();if(!q){toast('先輸入一個想了解的問題吧');return}const runs=q.match(/[a-z0-9]+|[\u3400-\u9fff]+/g)||[];const tokens=runs.flatMap(run=>/^[a-z0-9]+$/.test(run)?[run]:Array.from({length:Math.max(1,run.length-1)},(_,i)=>run.length>1?run.slice(i,i+2):run));if(q.includes('壞'))tokens.push('鬆動','損壞','修理','修繕');const scored=places.map(place=>({place,score:tokens.reduce((sum,token)=>sum+(`${place.name} ${place.intro} ${place.r||''} ${place.points.join(' ')} ${place.support.join(' ')} ${place.scenario||''}`).toLowerCase().includes(token)?1:0,0)})).sort((a,b)=>b.score-a.score);const best=scored[0];answer.hidden=false;if(!best||best.score===0){answer.textContent='我目前沒有在網站內容裡找到直接答案。你可以試試「壞掉」、「借用」、「添購」或「回收」，也可以打開地點清單閱讀各島情境。';return}const place=best.place;const all=[...(place.points||[]),...(place.support||[])];const relevant=all.find(line=>tokens.some(token=>line.toLowerCase().includes(token)))||all[0];answer.innerHTML=`${escapeHtml(relevant)}<br><a href="#places" data-guide-place="${place.id}">出自「${escapeHtml(place.name)}」→</a><small>　示意內容，請依實際校園規範確認。</small>`;answer.querySelector('[data-guide-place]').addEventListener('click',e=>{e.preventDefault();openPlace(place.id)})}
function escapeHtml(value=''){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
document.querySelectorAll('[data-theme-choice]').forEach(button=>button.addEventListener('click',()=>setTheme(button.dataset.themeChoice)));
document.querySelectorAll('[data-time]').forEach(button=>button.addEventListener('click',()=>setTimeMode(button.dataset.time)));
document.getElementById('reducedMotion').checked=mode.reduced;document.getElementById('reducedMotion').addEventListener('change',e=>{mode.reduced=e.target.checked;if(mode.reduced)mode.transitionStart=null;toast(mode.reduced?'減少動態已開啟':'動態效果已恢復')});
document.getElementById('searchInput').addEventListener('input',e=>renderCards(e.target.value));document.getElementById('guideAsk').addEventListener('click',guide);document.getElementById('guideInput').addEventListener('keydown',e=>{if(e.key==='Enter')guide()});
document.getElementById('resetView').addEventListener('click',()=>world?.resetView());document.getElementById('qualityBtn').addEventListener('click',e=>{mode.quality=mode.quality==='high'?'low':'high';e.currentTarget.setAttribute('aria-pressed',String(mode.quality==='low'));e.currentTarget.querySelector('span').textContent=mode.quality==='low'?'低畫質':'高畫質';world?.setQuality(mode.quality);toast(mode.quality==='low'?'低畫質已開啟，讓場景更順暢':'高畫質已開啟')});
document.getElementById('resetProgress').addEventListener('click',()=>{mode.done.clear();mode.quizzes.clear();saveState();renderProgress();renderCards(document.getElementById('searchInput').value);toast('探索進度已重設')});document.getElementById('clearBag').addEventListener('click',()=>{mode.inventory={shell:0,seed:0,flower:0,postcard:0};saveState();renderBag();toast('背包已清空')});
document.getElementById('helpBtn').addEventListener('click',()=>document.getElementById('helpDialog').showModal());document.getElementById('panelBackdrop').addEventListener('click',closePanel);document.getElementById('openCenter').addEventListener('click',()=>openPlace('center'));document.getElementById('quizStart').addEventListener('click',()=>{const next=places.find(place=>!mode.quizzes.has(place.id));openQuiz(next?.id||'center')});document.getElementById('certificateBtn').addEventListener('click',downloadCertificate);
document.getElementById('listMode').addEventListener('click',e=>{const list=document.getElementById('listView'),cards=document.getElementById('placeCards');const show=list.hidden;list.hidden=!show;cards.hidden=show;e.currentTarget.querySelector('span').textContent=show?'返回卡片':'純文字清單';if(show)list.scrollIntoView({behavior:mode.reduced?'instant':'smooth',block:'nearest'})});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!document.getElementById('quizDialog').open&& !document.getElementById('helpDialog').open){if(!document.getElementById('detailPanel').hidden)closePanel();else hideBubble()}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('searchInput').focus()}});
document.getElementById('sceneWrap').addEventListener('pointerdown',e=>{if(!e.target.closest('.resident-bubble'))hideBubble()});
