// 點擊沙灘貝殼可收集；允許清單版正常使用，3D 載入失敗時不會影響內容探索。

function printLesson(place){
  const popup=window.open('','_blank','width=760,height=850');
  if(!popup){toast('瀏覽器封鎖了列印視窗，請允許這個按鈕開啟列印頁。');return}
  const lesson=place.lesson||[];
  const questions=place.questions||[];
  const body='<main><h1>'+escapeHtml(place.name)+'｜帶領討論</h1><p>'+escapeHtml(place.intro)+'</p><h2>45 分鐘流程</h2><ol>'+lesson.map(item=>'<li><strong>'+item.minutes+' 分鐘｜'+escapeHtml(item.title)+'</strong><br>'+escapeHtml(item.body)+'</li>').join('')+'</ol><h2>討論問題</h2><ul>'+questions.map(q=>'<li>'+escapeHtml(q)+'</li>').join('')+'</ul><p class="note">示意草稿，請依實際教學情境與專業建議調整。這只是部分經驗的模擬，每個人的感受都不一樣。</p></main>';
  popup.document.write('<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><title>木語重生｜帶領流程</title><style>body{font:16px/1.8 system-ui,sans-serif;color:#243f36;padding:48px;max-width:760px;margin:auto}h1{color:#2f7a6b}li{margin:10px 0}.note{padding:14px;background:#f6f0e4;border-radius:8px;font-size:13px}@media print{body{padding:0}}</style>'+body+'<script>window.addEventListener("load",()=>window.print())</script></html>');popup.document.close();
}

